import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createOrderFulfillmentWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createOrderFulfillmentWorkflow(req.scope)
    .run({
      input: {
        order_id: "order_123",
        items: [{
          id: "orli_123",
          quantity: 1,
        }],
        additional_data: {
          send_oms: true
        }
      }
    })

  res.send(result)
}

